Here is the commit message:
mctp: i2c: fix skb memory leak in receive path

When 'midev->allow_rx' is false, the newly allocated skb isn't consumed
by netif_rx(), it needs to free the skb directly.

Fixes: f5b8abf9fc3d ("mctp i2c: MCTP I2C binding driver")
Signed-off-by: Haiyue Wang <haiyuewa@163.com>
Link: https://patch.msgid.link/20260305143240.97592-1-haiyuewa@163.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
In `mctp_i2c_recv()`, when `midev->allow_rx` is false, the function sets `status = NET_RX_DROP` and releases the spinlock, but does not free the skb that was just allocated. This results in a skb memory leak because the skb is never consumed by `netif_rx()` or freed.

Here is the patch:
 /* Processes incoming data that has been accumulated by the slave cb */
 static int mctp_i2c_recv(struct mctp_i2c_dev *midev)
 {
 	struct net_device *ndev = midev->ndev;
 	struct mctp_i2c_hdr *hdr;
 	struct mctp_skb_cb *cb;
 	struct sk_buff *skb;
 	unsigned long flags;
 	u8 pec, calc_pec;
 	size_t recvlen;
 	int status;

 	if (midev->rx_pos == 0)
 		return 0;

 	/* + 1 for the PEC */
 	if (midev->rx_pos < MCTP_I2C_MINLEN + 1) {
 		ndev->stats.rx_length_errors++;
 		return -EINVAL;
 	}
 	/* recvlen excludes PEC */
 	recvlen = midev->rx_pos - 1;

 	hdr = (void *)midev->rx_buffer;
 	if (hdr->command != MCTP_I2C_COMMANDCODE) {
 		ndev->stats.rx_dropped++;
 		return -EINVAL;
 	}

 	if (hdr->byte_count + offsetof(struct mctp_i2c_hdr, source_slave) != recvlen) {
 		ndev->stats.rx_length_errors++;
 		return -EINVAL;
 	}

 	pec = midev->rx_buffer[midev->rx_pos - 1];
 	calc_pec = i2c_smbus_pec(0, midev->rx_buffer, recvlen);
 	if (pec != calc_pec) {
 		ndev->stats.rx_crc_errors++;
 		return -EINVAL;
 	}

 	skb = netdev_alloc_skb(ndev, recvlen);
 	if (!skb) {
 		ndev->stats.rx_dropped++;
 		return -ENOMEM;
 	}

 	skb->protocol = htons(ETH_P_MCTP);
 	skb_put_data(skb, midev->rx_buffer, recvlen);
 	skb_reset_mac_header(skb);
 	skb_pull(skb, sizeof(struct mctp_i2c_hdr));
 	skb_reset_network_header(skb);

 	cb = __mctp_cb(skb);
 	cb->halen = 1;
 	cb->haddr[0] = hdr->source_slave >> 1;

 	/* We need to ensure that the netif is not used once netdev
 	 * unregister occurs
 	 */
 	spin_lock_irqsave(&midev->lock, flags);
 	if (midev->allow_rx) {
 		reinit_completion(&midev->rx_done);
 		spin_unlock_irqrestore(&midev->lock, flags);

 		status = netif_rx(skb);
 		complete(&midev->rx_done);
 	} else {
 		status = NET_RX_DROP;
 		spin_unlock_irqrestore(&midev->lock, flags);
+		kfree_skb(skb);
 	}

 	if (status == NET_RX_SUCCESS) {
 		ndev->stats.rx_packets++;
 		ndev->stats.rx_bytes += recvlen;
 	} else {
 		ndev->stats.rx_dropped++;
 	}
 	return 0;
 }



